import inspect
class Tool:
    def __init__(self, name, description, func, arguments, outputs):
        self.name, self.description, self.func = name, description, func
        self.arguments, self.outputs = arguments, outputs

    def to_string(self) -> str:
        args = ", ".join(f"{n}: {t}" for n, t in self.arguments)
        return (f"Tool Name: {self.name}, Description: {self.description}, "
                f"Arguments: {args}, Outputs: {self.outputs}")

    def __call__(self, *args, **kwargs):
        return self.func(*args, **kwargs)

def tool(func):
    sig = inspect.signature(func)
    args = [(p.name, p.annotation.__name__) for p in sig.parameters.values()]
    return Tool(func.__name__, func.__doc__, func, args, sig.return_annotation.__name__)

@tool
def calculator(a: int, b: int) -> int:
    """Multiply two integers."""
    return a * b
print(calculator.to_string())  # Tool Name: calculator, Description: Multiply two integers., Arguments: a: int, b: int, Outputs: int
